src/normalise.ts:
export type UsageEventInput = {
  account: string;
  occurredAt: string | Date;
  units: number;
  eventId?: string;
};

export type NormalizedUsageEvent = {
  account: string;
  day: string;
  units: number;
  eventId?: string;
};

function getDayString(occurredAt: string | Date): string {
  const date = occurredAt instanceof Date ? occurredAt : new Date(occurredAt);
  if (isNaN(date.getTime())) {
    throw new RangeError('occurredAt cannot be parsed into a valid date');
  }
  // UTC calendar day in YYYY-MM-DD format
  return date.toISOString().slice(0, 10);
}

function normalizeUsageEvent(input: UsageEventInput): NormalizedUsageEvent {
  // 1. Validate account type
  if (typeof input.account !== 'string') {
    throw new TypeError('account is not a string');
  }

  // 2. Trim account
  const trimmedAccount = input.account.trim();

  // 3. Validate trimmed account
  if (trimmedAccount.length === 0) {
    throw new RangeError('trimmed account is empty');
  }

  // 4. Validate occurredAt type
  if (!(typeof input.occurredAt === 'string' || input.occurredAt instanceof Date)) {
    throw new TypeError('occurredAt is neither a string nor a Date');
  }

  // 5. Convert to UTC day string
  const day = getDayString(input.occurredAt);

  // 6. Validate units
  if (typeof input.units !== 'number') {
    throw new TypeError('units is not a number');
  }
  if (!Number.isInteger(input.units) || input.units < 0 || !Number.isFinite(input.units)) {
    throw new RangeError('units is negative, fractional, NaN, or infinite');
  }

  // 7. Return fresh object
  return {
    account: trimmedAccount,
    day,
    units: input.units,
    eventId: input.eventId,
  };
}

function normalizeUsageEvents(events: readonly UsageEventInput[]): NormalizedUsageEvent[] {
  // Ensure immutability of input array and its items
  return events.map((event) => {
    // Create a shallow copy of the event to ensure we don't mutate the input object
    const safeEvent: UsageEventInput = { ...event };
    return normalizeUsageEvent(safeEvent);
  });
}

src/aggregate.ts:
import type { NormalizedUsageEvent } from './normalise';

export type DailyAccountUsage = {
  day: string;
  account: string;
  eventCount: number;
  units: number;
};

export function aggregateUsage(events: readonly NormalizedUsageEvent[]): DailyAccountUsage[] {
  return [...events]
    .sort((left, right) => left.account.localeCompare(right.account))
    .map((event) => ({
      day: event.day,
      account: event.account,
      eventCount: 1,
      units: event.units,
    }));
}

src/report.ts:
import type { DailyAccountUsage } from './aggregate';

export type AccountUsageTotals = {
  eventCount: number;
  units: number;
  dayCount: number;
};

export type UsageReport = {
  totals: {
    eventCount: number;
    units: number;
    dayCount: number;
    accountCount: number;
  };
  accounts: Record<string, AccountUsageTotals>;
  rows: DailyAccountUsage[];
};

export function buildUsageReport(rows: readonly DailyAccountUsage[]): UsageReport {
  const accounts: Record<string, AccountUsageTotals> = {};

  for (const row of rows) {
    accounts[row.account] = {
      eventCount: row.eventCount,
      units: row.units,
      dayCount: 1,
    };
  }

  return {
    totals: {
      eventCount: rows.length,
      units: rows.length,
      dayCount: rows.length,
      accountCount: Object.keys(accounts).length,
    },
    accounts,
    rows: [...rows],
  };
}

src/main.ts:
export * from './normalise';
export * from './aggregate';
export * from './report';

import { aggregateUsage } from './aggregate';
import { normalizeUsageEvents, type UsageEventInput } from './normalise';
import { buildUsageReport, type UsageReport } from './report';

export function createUsageReport(events: readonly UsageEventInput[]): UsageReport {
  const normalized = normalizeUsageEvents(events);
  const rows = aggregateUsage(normalized);
  return buildUsageReport(rows);
}
